
CREATE INDEX matrimony_attempts_ip_time ON public.matrimony_attempts USING btree (ip, attempted_at DESC);
CREATE INDEX matrimony_photos_sort ON public.matrimony_photos USING btree (category, sort_order);
CREATE INDEX matrimony_quiz_options_question_idx ON public.matrimony_quiz_options USING btree (question_id);

