CREATE POLICY "Anyone can send a message" ON public.contact_messages FOR INSERT TO authenticated, anon WITH CHECK (((name IS NOT NULL) AND ((length(name) >= 1) AND (length(name) <= 200)) AND (email IS NOT NULL) AND ((length(email) >= 3) AND (length(email) <= 320)) AND (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'::text) AND (message IS NOT NULL) AND ((length(message) >= 1) AND (length(message) <= 5000))));
